// RollbackMutation is the resolver for the rollbackMutation field.
func (r *mutationResolver) RollbackMutation(ctx context.Context, mutationID string) (bool, error) {
	dur := r.durabilityEngine()
	if dur == nil {
		return false, fmt.Errorf("durability engine is not configured")
	}

	claims := GetAuthClaims(ctx)
	if claims == nil {
		return false, fmt.Errorf("unauthorized: no authenticated claims") // P3-2: never a "system" rollback by default
	}
	actorID := "system"
	familyGroup := ""
	if !claims.IsGlobalAdmin() { // P3-2: only global admins roll back system-wide
		actorID = claims.UserID
		familyGroup = claims.FamilyGroup
	}

	res, err := dur.Rollback(ctx, actorID, familyGroup, mutationID)
	if err != nil {
		return false, err
	}
	return !res.AlreadyUndone, nil
}


// Users is the resolver for the users field.
func (r *queryResolver) Users(ctx context.Context) ([]*model.User, error) {
	var dbUsers []dbmodels.User
	if err := r.DB.DB.Find(&dbUsers).Error; err != nil {
		return nil, err
	}

	var users []*model.User
	for _, u := range dbUsers {
		users = append(users, &model.User{
			ID:          u.ID,
			PlatformID:  u.PlatformID,
			Name:        u.Name,
			Role:        u.Role,
			FamilyGroup: u.FamilyGroup,
			CreatedAt:   u.CreatedAt,
		})
	}
	return users, nil
}

