// MutationLogs is the resolver for the mutationLogs field.
func (r *queryResolver) MutationLogs(ctx context.Context, familyGroup *string, topic *string, limit *int) ([]*model.MutationLog, error) {
	_, fg, err := r.resolveTenantAndActor(ctx, familyGroup)
	if err != nil {
		return nil, err
	}

	var dbLogs []dbmodels.MutationLog
	query := r.DB.DB.Model(&dbmodels.MutationLog{})

	if fg != "" && fg != "default" {
		query = query.Where("family_group = ?", fg)
	}
	if topic != nil && *topic != "" {
		query = query.Where("topic = ?", *topic)
	}
	lim := 50
	if limit != nil && *limit > 0 {
		lim = *limit
	}

	if err := query.Order("created_at DESC").Limit(lim).Find(&dbLogs).Error; err != nil {
		return nil, err
	}

	var res []*model.MutationLog
	for i := range dbLogs {
		res = append(res, toModelMutationLog(&dbLogs[i]))
	}
	return res, nil
}

// AuditSessions is the resolver for the auditSessions field.
func (r *queryResolver) AuditSessions(ctx context.Context, familyGroup *string, limit *int) ([]*model.AuditSession, error) {
	lim := 50
	if limit != nil && *limit > 0 {
		lim = *limit
	}

	claims := GetAuthClaims(ctx)
	var fg string
	var err error
	if claims.IsGlobalAdmin() && (familyGroup == nil || *familyGroup == "" || *familyGroup == "*") { // P3-2
		// Admin requesting system-wide or default unscoped view
		fg = ""
	} else {
		_, fg, err = r.resolveTenantAndActor(ctx, familyGroup)
		if err != nil {
			return nil, err
		}
	}

	var dbSessions []dbmodels.AuditSession
	q := r.DB.DB.Model(&dbmodels.AuditSession{})
	if fg != "" {
		q = q.Joins("JOIN users ON (users.id::text = audit_sessions.user_id OR users.platform_id = audit_sessions.user_id)").Where("users.family_group = ?", fg)
	}

	if err := q.Order("audit_sessions.start_time DESC").Limit(lim).Find(&dbSessions).Error; err != nil {
		return nil, err
	}

	out := make([]*model.AuditSession, len(dbSessions))
	for i, s := range dbSessions {
		out[i] = &model.AuditSession{
			ID:              s.ID,
			UserID:          s.UserID,
			Source:          s.Source,
			UserPrompt:      s.UserPrompt,
			Status:          s.Status,
			TotalDurationMs: int(s.TotalDurationMs),
			StartTime:       s.StartTime,
		}
	}
	return out, nil
}

// UserSessions is the resolver for the userSessions field.
func (r *queryResolver) UserSessions(ctx context.Context, familyGroup *string) ([]*model.UserSessionSummary, error) {
	type sessionRow struct {
		UserID            string    `gorm:"column:user_id"`
		Source            string    `gorm:"column:source"`
		TotalInteractions int       `gorm:"column:total_interactions"`
		LastActive        time.Time `gorm:"column:last_active"`
	}

	claims := GetAuthClaims(ctx)
	var fg string
	var err error
	if claims.IsGlobalAdmin() && (familyGroup == nil || *familyGroup == "" || *familyGroup == "*") { // P3-2
		// Admin requesting system-wide view
		fg = ""
	} else {
		_, fg, err = r.resolveTenantAndActor(ctx, familyGroup)
		if err != nil {
			return nil, err
		}
	}

	var rows []sessionRow
	q := r.DB.DB.Model(&dbmodels.AuditSession{})
	if fg != "" {
		q = q.Joins("JOIN users ON (users.id::text = audit_sessions.user_id OR users.platform_id = audit_sessions.user_id)").Where("users.family_group = ?", fg)
	}

	err = q.Select("audit_sessions.user_id, MAX(source) as source, COUNT(audit_sessions.id) as total_interactions, MAX(start_time) as last_active").
		Group("audit_sessions.user_id").
		Order("last_active DESC").
		Scan(&rows).Error
	if err != nil {
		return nil, err
	}

	out := make([]*model.UserSessionSummary, len(rows))
	for i, row := range rows {
		out[i] = &model.UserSessionSummary{
			UserID:            row.UserID,
			Source:            row.Source,
			TotalInteractions: row.TotalInteractions,
			LastActive:        row.LastActive,
		}
	}
	return out, nil
}

// Mutation returns MutationResolver implementation.
func (r *Resolver) Mutation() MutationResolver { return &mutationResolver{r} }

// Query returns QueryResolver implementation.
func (r *Resolver) Query() QueryResolver { return &queryResolver{r} }

type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }

func uintToStr(id uint) string {
	return strconv.FormatUint(uint64(id), 10)
}

func tableNameForEntity(entityType string) (string, error) {
	return durability.ResolveRollbackTable(entityType)
}

