func toModelMutationLog(m *dbmodels.MutationLog) *model.MutationLog {
	var before *string
	if m.BeforeJSON != "" {
		before = &m.BeforeJSON
	}
	var after *string
	if m.AfterJSON != "" {
		after = &m.AfterJSON
	}
	return &model.MutationLog{
		ID:          m.ID,
		UserID:      m.UserID,
		FamilyGroup: m.FamilyGroup,
		Topic:       m.Topic,
		Action:      m.Action,
		EntityType:  m.EntityType,
		EntityID:    m.EntityID,
		BeforeJSON:  before,
		AfterJSON:   after,
		Summary:     m.Summary,
		IsUndone:    m.IsUndone,
		CreatedAt:   m.CreatedAt,
	}
}
